/bin/bash -lc "node --input-type=module <<'NODE'
const cases = [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
]
for (const [path, product, price, related] of cases) {
  const start = performance.now()
  const response = await fetch("'`http://localhost:3100${path}`)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = '"''
  const seen = {}
  const markers = {
    frame: 'Signal Shop collection',
    detailsFallback: 'Loading product details',
    product: "'`<h1>${product}</h1>`,
    price,
    relatedFallback: '"'Loading related products',
    related: "'`<p>${related}</p>`,
  }
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    html += decoder.decode(value, { stream: true })
    for (const [key, marker] of Object.entries(markers)) {
      if (!(key in seen) && html.includes(marker)) seen[key] = Math.round(performance.now() - start)
    }
  }
  console.log(JSON.stringify({ path, status: response.status, seen, bytes: html.length }))
}
NODE'

